def apply(D):
 for l,d in D.items():
  d.update(COPY[l])
  d['fallbackbusiness']={'pl':'Bez JavaScript wybierz usługę ręcznie. Zakres i wycenę ustalamy indywidualnie, po sprawdzeniu konfliktu interesów. Przycisk otwiera program pocztowy — uzupełnij w nim temat i treść lub napisz na podany adres.','en':'Without JavaScript, select the service manually. Scope and pricing are agreed individually after conflict screening. The button opens your email app — add a subject and message there, or use the email address shown.','de':'Ohne JavaScript wählen Sie die Leistung bitte manuell. Umfang und Preis werden nach Prüfung auf Interessenkonflikte individuell abgestimmt. Die Schaltfläche öffnet Ihr E-Mail-Programm — ergänzen Sie Betreff und Nachricht oder nutzen Sie die angegebene E-Mail-Adresse.'}[l]
  d['formbusiness']=d['conflict']+' '+{'pl':'Opisz lokal, etap i potrzebny zakres wsparcia. Zakres i wycenę ustalamy indywidualnie; role, strony umowy i odpowiedzialność potwierdzamy przed realizacją.','en':'Describe the premises, current stage and support needed. Scope and pricing are agreed individually; roles, contracting parties and responsibilities are confirmed before execution.','de':'Beschreiben Sie das Objekt, den aktuellen Stand und den Unterstützungsbedarf. Umfang und Preis stimmen wir individuell ab; Rollen, Vertragsparteien und Verantwortung werden vor der Ausführung bestätigt.'}[l]
  d['faq'][3][1]=d['faqcrew']
  d['faq'][4][1]=d['faqcost']
  d['steps'][2][1]={'pl':'Zakres, role, strony umowy, odpowiedzialność i poprawki potwierdzamy na piśmie przed realizacją. Dalsze prace dopiero po zamknięciu formalności i osobnym uzgodnieniu.','en':'Scope, roles, contracting parties, responsibilities and remedial arrangements are confirmed in writing before execution. Further work only after formal requirements and separate agreement.','de':'Umfang, Rollen, Vertragsparteien, Verantwortung und Nachbesserungen bestätigen wir vor der Ausführung schriftlich. Weitere Arbeiten erst nach Abschluss der Formalitäten und gesonderter Vereinbarung.'}[l]
 return D
